#!/usr/bin/env bash
set -euo pipefail

DEST="${1:-.env.opensigner}"

if [[ -f "$DEST" ]]; then
  echo "gen-secrets: $DEST already exists, skipping" >&2
  exit 0
fi

JWT_SECRET=$(openssl rand -base64 48)
SHARE_ENCRYPTION_KEY=$(openssl rand -hex 32)
DB_PASS=$(openssl rand -hex 16)

cat > "$DEST" <<EOF
# Generated by scripts/gen-secrets.sh — do not commit
JWT_SECRET=${JWT_SECRET}
SHARE_ENCRYPTION_KEY=${SHARE_ENCRYPTION_KEY}
POSTGRES_PASSWORD=${DB_PASS}
AUTH_SERVICE_DB_PASS=${DB_PASS}
HOT_STORAGE_DB_PASS=${DB_PASS}
COLD_STORAGE_DB_PASS=${DB_PASS}
EOF

echo "gen-secrets: wrote $DEST" >&2
